// 是否是在客户端打开
contextBridge.exposeInMainWorld('isInBitBrowser', true)
contextBridge.exposeInMainWorld('bitapi', true)
contextBridge.exposeInMainWorld('isMac', process.platform === 'darwin')
contextBridge.exposeInMainWorld('isOldWindows', process.platform === 'win32' && +process.getSystemVersion().split('.').shift() < 10)
contextBridge.exposeInMainWorld('platformVersion', process.getSystemVersion())

// loading时，直接退出
contextBridge.exposeInMainWorld('exitWhenLoading', () => {
  ipcRenderer.send('exit-when-loading')
})

